package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FailuresToAlertVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property failures to alert of observed probe ")
  void test_failures_to_alert_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> FailuresToAlertVO.tryFrom(null));
    Assertions.assertEquals(1, FailuresToAlertVO.from(1).getFailuresToAlert());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> FailuresToAlertVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", FailuresToAlertVO.from(1).toString());
  }
}
